package com.sarc.backend.model;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.*;
@Entity @Table(name="usuarios",uniqueConstraints=@UniqueConstraint(name="uk_usuario_identificacion",columnNames="identificacion")) public class Usuario { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank private String identificacion; @NotBlank private String nombre; @Enumerated(EnumType.STRING) @Column(nullable=false) private Enums.TipoUsuario tipo; @Enumerated(EnumType.STRING) private Enums.EstadoUsuario estado=Enums.EstadoUsuario.ACTIVO; private LocalDate fechaNacimiento; @Enumerated(EnumType.STRING) private Enums.Genero genero; private String telefono,correo,direccion,ciudad; @ManyToOne private Especialidad especialidad; @Enumerated(EnumType.STRING) private Enums.Turno turno; public Long getId(){return id;} public String getIdentificacion(){return identificacion;} public void setIdentificacion(String v){identificacion=v;} public String getNombre(){return nombre;} public void setNombre(String v){nombre=v;} public Enums.TipoUsuario getTipo(){return tipo;} public void setTipo(Enums.TipoUsuario v){tipo=v;} public Enums.EstadoUsuario getEstado(){return estado;} public void setEstado(Enums.EstadoUsuario v){estado=v;} public LocalDate getFechaNacimiento(){return fechaNacimiento;} public void setFechaNacimiento(LocalDate v){fechaNacimiento=v;} public String getTelefono(){return telefono;} public void setTelefono(String v){telefono=v;} public String getCorreo(){return correo;} public void setCorreo(String v){correo=v;} public Especialidad getEspecialidad(){return especialidad;} public void setEspecialidad(Especialidad v){especialidad=v;} public Enums.Turno getTurno(){return turno;} public void setTurno(Enums.Turno v){turno=v;} }
